arguments.content:
{
  "version": "V7",
  "phase": "grading",
  "segments": [
    {
      "id": "段1",
      "content": "WLOG排序 a₁ < a₂ < ... < aₙ（通过施加一个置换），将一般情况化简为有序情况",
      "features": ["对称性化简"]
    },
    {
      "id": "段2",
      "content": "定义关键量 x = a₁ + ... + a_{n-1}（除最大元外所有元素之和），作为情况划分的基准",
      "features": ["关键量定义"]
    },
    {
      "id": "段3",
      "content": "声明对 n 施加强归纳策略",
      "features": ["强归纳策略"]
    },
    {
      "id": "段4",
      "content": "按 M 中元素相对 x 的位置将问题分为三种情况（情况划分的总纲）",
      "features": ["情况划分"]
    },
    {
      "id": "段5",
      "content": "Case 1 条件声明：x ∈ M 且存在 y ∈ M 使 y > x，由此推出 n ≥ 3",
      "features": ["情况划分"]
    },
    {
      "id": "段6",
      "content": "在 n-1 个小元素中定义'bad'指标 i：当 x - aᵢ ∈ M 或 s - aᵢ ∈ M 时为bad——引入bad/good指标的概念",
      "features": ["概念引入"]
    },
    {
      "id": "段7",
      "content": "构造从bad指标到 M\\{x} 的注入映射（x - aᵢ 映到 M\\{x}，s - aᵢ > x 映到 M∩(x,∞)），证明注入性",
      "features": ["鸽巢论证"]
    },
    {
      "id": "段8",
      "content": "由 |M\\{x}| = n-2 推出至多 n-2 个bad指标，而共有 n-1 个指标，故至少存在一个good指标 r（x - aᵣ ∉ M 且 s - aᵣ ∉ M）——鸽巢计数结论",
      "features": ["鸽巢论证"]
    },
    {
      "id": "段9",
      "content": "令 t = x - aᵣ，构造子问题 M' = M ∩ (-∞, t]，并计数得 |M'| ≤ n-3（因 x 和 y 均被排除）",
      "features": ["子问题构造", "计数论证"]
    },
    {
      "id": "段10",
      "content": "对 n-2 个剩余元素（排除 aᵣ 和 aₙ）配 M' 应用归纳假设，得到排列 p'",
      "features": ["归纳应用"]
    },
    {
      "id": "段11",
      "content": "构造完整排列：先放 p'，再放 aᵣ，再放 aₙ（通过交换使 aₙ 位于倒数第二位）",
      "features": ["排列构造"]
    },
    {
      "id": "段12",
      "content": "验证 Case 1：aᵣ 之前的所有前缀和 ≤ t 且避开 M'；到 aᵣ 的和为 s - aₙ 避开 M（由 r 的选取）；最终和为 s ∉ M",
      "features": ["前缀和验证"]
    },
    {
      "id": "段13",
      "content": "Case 2 条件声明：x ∉ M 且存在 y ∈ M 使 y > x，计数得 |M ∩ (-∞, x]| ≤ n-2",
      "features": ["情况划分", "计数论证"]
    },
    {
      "id": "段14",
      "content": "令 M' = M ∩ (-∞, x]，对 a₁,...,a_{n-1} 配 M' 应用归纳假设（其和为 x ∉ M'）",
      "features": ["子问题构造", "归纳应用"]
    },
    {
      "id": "段15",
      "content": "边界处理：若 M' 为空则用恒等排列；否则取归纳所得 p'，在末尾追加 aₙ 扩展为完整排列",
      "features": ["边界处理", "排列构造"]
    },
    {
      "id": "段16",
      "content": "验证 Case 2：前 n-1 步的前缀和均 ≤ x 且避开 M'；最终和为 s ∉ M",
      "features": ["前缀和验证"]
    },
    {
      "id": "段17",
      "content": "Case 3 条件声明：所有 m ∈ M 满足 m ≤ x；令 z = max(M)，构造子问题 M' = M\\{z}",
      "features": ["情况划分", "子问题构造"]
    },
    {
      "id": "段18",
      "content": "对 a₁,...,a_{n-1} 配 M'（|M'| = n-2）应用归纳假设，得到排列 p'",
      "features": ["归纳应用"]
    },
    {
      "id": "段19",
      "content": "交换技巧处理冲突：若 p' 的某前缀和在位置 k 等于 z，则将 aₙ 放到位置 k（因 aₙ > a_{p'(k)} 可跳过 z），将 a_{p'(k)} 放到末尾",
      "features": ["交换技巧", "排列构造"]
    },
    {
      "id": "段20",
      "content": "无冲突情况验证：若没有前缀和等于 z，则 p' 已避开 M 的全部元素（M = M' ∪ {z}，z 从未被命中）",
      "features": ["前缀和验证"]
    },
    {
      "id": "段21",
      "content": "将一般情况（未排序的 a）归约到排序情况：通过与排序置换复合即可",
      "features": ["归约"]
    }
  ]
}
